{"path": "/tmp/sv-b617f9fcbb2244dd91f16f5edb374dfc/RecipeShare/Services/RecipeService.cs", "file_text": "using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out pizza dough on a floured surface.\n3. Spread crushed tomatoes evenly over dough.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil."
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook spaghetti in salted boiling water until al dente.\n2. Crisp guanciale in a pan over medium heat.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, add egg mixture, and toss quickly.\n6. Serve immediately with extra pecorino."
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nTomato sauce\nHeavy cream\nOnion\nGarlic\nGinger",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or bake chicken until charred.\n3. Sauté onion, garlic, and ginger in a pan.\n4. Add tomato sauce and simmer 15 minutes.\n5. Stir in cream and garam masala.\n6. Add chicken pieces and simmer 10 minutes.\n7. Serve with basmati rice or naan."
        },
        new Recipe
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nEggs",
            Steps = "1. Soak rice noodles in warm water for 30 minutes.\n2. Mix tamarind paste, fish sauce, and sugar for the sauce.\n3. Press and cube tofu, then pan-fry until golden.\n4. Scramble eggs in the same pan.\n5. Add drained noodles and sauce, toss well.\n6. Add bean sprouts and green onions.\n7. Serve with crushed peanuts and lime wedges."
        },
        new Recipe
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco shells\nLettuce\nTomatoes\nCheddar cheese\nSour cream\nCumin\nChili powder\nOnion\nGarlic",
            Steps = "1. Sauté onion and garlic in a skillet.\n2. Add ground beef, cumin, and chili powder.\n3. Cook until beef is browned and seasoned.\n4. Warm taco shells in the oven.\n5. Assemble with beef, lettuce, tomato, cheese, and sour cream."
        },
        new Recipe
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt",
            Steps = "1. Halve and pit avocados, scoop into a bowl.\n2. Mash to desired consistency.\n3. Stir in lime juice, diced onion, jalapeño, and tomato.\n4. Add chopped cilantro and salt to taste.\n5. Serve immediately with tortilla chips."
        },
        new Recipe
        {
            Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
            Steps = "1. Preheat oven to 425°F (220°C).\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until thick.\n4. Fold chocolate mixture into eggs.\n5. Add flour and vanilla, mix gently.\n6. Pour into greased ramekins.\n7. Bake 12-14 minutes until edges are set but center jiggles.\n8. Invert onto plates and serve immediately."
        }
    };

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe != null && stars >= 1 && stars <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }
}
"}

