@rendermode InteractiveServer
@using RecipeShare.Services

<div class="star-rating">
    <span class="rating-label">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "filled" : "")"
              @onclick="() => SubmitRating(star)"
              title="@star star(s)">★</span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
    @if (_averageRating > 0)
    {
        <span class="rating-average">Average: @_averageRating.ToString("F1") / 5</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private int _selectedRating;
    private bool _submitted;
    private double _averageRating;

    protected override void OnInitialized()
    {
        LoadRating();
    }

    private void SubmitRating(int stars)
    {
        _selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        _submitted = true;
        LoadRating();
    }

    private void LoadRating()
    {
        var recipe = RecipeService.GetById(RecipeId);
        _averageRating = recipe?.AverageRating ?? 0;
    }
}

